"use strict";

// The NEGATIVE control that makes RWF-026 sound rather than merely
// conservative. It carries the identical always-throwing call in four
// positions the language does NOT require to be evaluated, so its later
// export must REMAIN authoritative:
//
//  1. `MODE && bail()`   -- a logical operator's RIGHT operand, skipped
//                           entirely for a falsy left operand;
//  2. `() => sink(bail())` -- an arrow BODY, run only when called;
//  3. `function f(x = bail())` -- a default PARAMETER, evaluated only on a
//                           call that omits the argument;
//  4. `class C { field = bail(); }` -- a class INSTANCE field, evaluated
//                           per-construction, not at class-definition time.
//
// All four are proven safe in-process in the ground-truth fixture's `c.js`
// and `positions.js`. Treating any of them like a required position would
// withdraw authority from an export that is genuinely reached, which is a
// false refusal rather than conservatism.
function dangerousOp(input) {
  return "danger:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("throws only on invocation, or on a truthy left operand");
}

function sink(a) {
  return a;
}

function withDefault(x = bail()) {
  return x;
}

class Holder {
  field = bail();
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  const skipped = process.env.FIXTURE_LIB_FLAG && bail();
  const callback = () => sink(bail());
  void skipped;
  void callback;
}

safeOp.withDefault = withDefault;
safeOp.Holder = Holder;
module.exports = safeOp;
